using System.ComponentModel;
using System.Net;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tool instances ---
var notebook = new Notebook();

// --- Build the agent ---
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(notebook.SaveNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

var agent = new ChatClientBuilder(new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .BuildAIAgent(
        instructions: """
            You are a research assistant. When given a topic:
            1. Search the web 2-3 times with varied queries to gather information.
            2. Save important findings as notes using the save_note tool.
            3. Review your notes with get_notes, then provide a concise summary
               of everything you learned. Cite your sources where possible.
            """,
        name: "ResearchAgent",
        description: "Researches topics using web search and note-taking",
        tools: tools);

// --- Run ---
var topic = args.Length > 0 ? string.Join(' ', args) : PromptForTopic();
Console.WriteLine($"\n🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var result = await agent.RunAsync(
    $"Research the following topic and provide a summary: {topic}",
    session,
    runOptions);

Console.WriteLine("\n📋 Agent response:\n");
foreach (var message in result.Messages.Where(m => m.Role == ChatRole.Assistant))
{
    var text = message.Text;
    if (!string.IsNullOrWhiteSpace(text))
        Console.WriteLine(text);
}

Console.WriteLine($"\n📝 Notes collected: {notebook.Count}");

// --- Helpers ---
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine();
    return string.IsNullOrWhiteSpace(input)
        ? throw new InvalidOperationException("A topic is required.")
        : input;
}

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------

/// <summary>Searches the web for information on a query.</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information. Returns a snippet of relevant results.")]
    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            // Use DuckDuckGo lite (no API key required)
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var snippets = ExtractSnippets(html, maxSnippets: 5);
            return snippets.Count > 0
                ? $"Search results for \"{query}\":\n" + string.Join("\n\n", snippets)
                : $"No results found for \"{query}\".";
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    private static List<string> ExtractSnippets(string html, int maxSnippets)
    {
        var snippets = new List<string>();
        // DuckDuckGo lite returns results in table rows with class="result-snippet"
        var searchArea = html;
        var snippetMarker = "class=\"result-snippet\"";
        var linkMarker = "class=\"result-link\"";
        var idx = 0;

        while (snippets.Count < maxSnippets)
        {
            var snippetPos = searchArea.IndexOf(snippetMarker, idx, StringComparison.Ordinal);
            if (snippetPos < 0) break;

            var tdClose = searchArea.IndexOf("</td>", snippetPos, StringComparison.Ordinal);
            if (tdClose < 0) break;

            var start = searchArea.IndexOf('>', snippetPos + snippetMarker.Length) + 1;
            if (start <= 0 || start >= tdClose) { idx = snippetPos + 1; continue; }

            var snippet = StripHtml(searchArea[start..tdClose]).Trim();

            // Try to find a nearby link
            var linkStart = searchArea.LastIndexOf(linkMarker, snippetPos, Math.Min(snippetPos, 500), StringComparison.Ordinal);
            var link = "";
            if (linkStart >= 0)
            {
                var hrefPos = searchArea.IndexOf("href=\"", linkStart, StringComparison.Ordinal);
                if (hrefPos >= 0 && hrefPos < snippetPos)
                {
                    var hrefStart = hrefPos + 6;
                    var hrefEnd = searchArea.IndexOf('"', hrefStart);
                    if (hrefEnd > hrefStart)
                        link = searchArea[hrefStart..hrefEnd];
                }
            }

            if (snippet.Length > 20)
            {
                var entry = string.IsNullOrEmpty(link) ? $"- {snippet}" : $"- {snippet}\n  Source: {link}";
                snippets.Add(entry);
            }
            idx = tdClose;
        }

        return snippets;
    }

    private static string StripHtml(string html)
    {
        var result = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
        result = WebUtility.HtmlDecode(result);
        return System.Text.RegularExpressions.Regex.Replace(result, @"\s+", " ");
    }
}

/// <summary>In-memory notebook for storing research findings.</summary>
sealed class Notebook
{
    private readonly List<(DateTime Timestamp, string Title, string Content)> _notes = [];

    public int Count => _notes.Count;

    [Description("Save a research note with a title and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Detailed content of the finding")] string content)
    {
        _notes.Add((DateTime.UtcNow, title, content));
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Retrieve all saved research notes to review findings before summarizing.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"Note #{i + 1} — {n.Title}\n{n.Content}"));
    }
}

